/**
 * Pure tests for the S5b inbox triage dry-run planner.
 *
 * The oracle fixture is generated by `apps/crq-python/triage_plan_vectors.py`
 * from the PRODUCTION Python `crq_repair.triage.phase(..., dry_run=True)`.
 * Every inbox row, retained review, Git fact, recovered anchor and context
 * outcome is injected; the test compares the dry-run report, the exact ordered
 * Git reads, the seam calls and the number of monotonic-clock reads, so
 * ordering, eligibility, dedupe, limits, the deadline and missing-evidence
 * admission move only when Python moves.
 *
 * No process, filesystem write, real clock, provider or network participates.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import {
  missingEvidence,
  planTriageDryRun,
  TriagePlanRefusal,
  type TriageContextOutcome,
  type TriagePlanReport,
  type TriagePlanResult,
  type TriageRepo,
} from '../../../src/policy/crq/triagePlan.js';
import { JsonObject, parseJsonValue, type JsonValue } from '../../../src/policy/crq/jsonValue.js';

interface Row {
  file: string;
  row: unknown;
}

interface Spec {
  rows: Row[];
  reviews: unknown[];
  tip: string;
  maximum: number;
  seconds: number;
  clock: { start: number; step: number };
  entries: string[];
  commit_dates: Record<string, string>;
  lineage: { target: string; path: string; result: string | null }[];
  proven_deleted: { target: string; path: string }[];
  deleting: { path: string; commit: string }[];
  recovery: { enabled: boolean; anchors: Record<string, unknown> };
  context_errors: Record<string, string>;
}

interface Case {
  name: string;
  input: Spec;
  ts_refuses: boolean;
  raises?: string;
  result?: Record<string, unknown>;
  repo_calls?: string[][];
  recover_calls?: string[];
  context_calls?: Record<string, unknown>[];
  clock_reads?: number;
}

const FIXTURE_URL = new URL(
  '../../../apps/crq-python/fixtures/crq-triage-plan/cases.json',
  import.meta.url,
);
const fixture = JSON.parse(readFileSync(FIXTURE_URL, 'utf8')) as { cases: Case[] };

/** Re-parse through the production JSON reader so rows are real `JsonObject`s. */
function json(value: unknown): JsonValue {
  return parseJsonValue(JSON.stringify(value));
}

function object(value: unknown): JsonObject {
  const parsed = json(value);
  if (!(parsed instanceof JsonObject)) throw new Error('fixture value is not an object');
  return parsed;
}

/** Python's `sorted(glob)`: file names are ASCII, so code-unit order is exact. */
function sortedRows(rows: Row[]): JsonObject[] {
  return [...rows]
    .sort((a, b) => (a.file < b.file ? -1 : a.file > b.file ? 1 : 0))
    .map((entry) => object(entry.row));
}

/** The oracle sorts each run of target-date reads: Python asks in set order. */
function normalize(calls: string[][]): string[][] {
  const result: string[][] = [];
  let run: string[][] = [];
  const flush = (): void => {
    run.sort((a, b) => (a[1] as string).localeCompare(b[1] as string));
    result.push(...run);
    run = [];
  };
  for (const call of calls) {
    if (call[0] === 'commit_date') {
      run.push(call);
    } else {
      flush();
      result.push(call);
    }
  }
  flush();
  return result;
}

interface Replay {
  readonly result: TriagePlanResult;
  readonly repoCalls: string[][];
  readonly recoverCalls: string[];
  readonly contextCalls: Record<string, unknown>[];
  readonly clockReads: number;
}

function replay(spec: Spec): Replay {
  const repoCalls: string[][] = [];
  const recoverCalls: string[] = [];
  const contextCalls: Record<string, unknown>[] = [];
  let clockReads = 0;
  const repo: TriageRepo = {
    beginInvocation: () => {
      repoCalls.push(['begin']);
    },
    commitDate: (target) => {
      repoCalls.push(['commit_date', target]);
      const date = spec.commit_dates[target];
      if (date === undefined) throw new Error(`unscripted commit date ${target}`);
      return `${date}\n`;
    },
    entryPaths: (tip) => {
      repoCalls.push(['entries', tip]);
      return new Set(spec.entries);
    },
    lineage: (target, tip, path) => {
      repoCalls.push(['lineage', target, tip, path]);
      const hit = spec.lineage.find((item) => item.target === target && item.path === path);
      return hit === undefined ? null : hit.result;
    },
    provenDeleted: (target, tip, path) => {
      repoCalls.push(['proven_deleted', target, tip, path]);
      return spec.proven_deleted.some((item) => item.target === target && item.path === path);
    },
    deletingCommit: (tip, path) => {
      repoCalls.push(['deleting', tip, path]);
      const hit = spec.deleting.find((item) => item.path === path);
      return `${hit === undefined ? '' : hit.commit}\n`;
    },
  };
  const findingId = (row: JsonObject): string => {
    const finding = row.get('finding');
    return finding instanceof JsonObject ? (finding.get('id') as string) : '';
  };
  const result = planTriageDryRun({
    rows: sortedRows(spec.rows),
    reviews: spec.reviews.map(json),
    tip: spec.tip,
    maximum: spec.maximum,
    seconds: spec.seconds,
    clock: () => {
      const value = spec.clock.start + clockReads * spec.clock.step;
      clockReads += 1;
      return value;
    },
    repo,
    ...(spec.recovery.enabled
      ? {
          recoverAnchor: (row: JsonObject): JsonObject | null => {
            const id = findingId(row);
            recoverCalls.push(id);
            const anchor = spec.recovery.anchors[id];
            return anchor === undefined ? null : object(anchor);
          },
        }
      : {}),
    prepareContext: (request): TriageContextOutcome => {
      const id = findingId(request.row);
      contextCalls.push({
        finding_id: id,
        tip: request.tip,
        escalate: request.escalate,
        recovered: request.recoveredAnchor !== null,
      });
      const name = spec.context_errors[id];
      return name === undefined ? { kind: 'ready' } : { kind: 'error', errorType: name };
    },
  });
  return { result, repoCalls: normalize(repoCalls), recoverCalls, contextCalls, clockReads };
}

/** The report in the oracle's snake_case, field for field. */
function snake(report: TriagePlanReport): Record<string, unknown> {
  return {
    total: report.total,
    judged: report.judged,
    unjudged: report.unjudged,
    counts: report.counts,
    delivered: report.delivered,
    delivery_deferred: report.deliveryDeferred,
    context_errors: report.contextErrors.map((error) => ({
      finding_id: error.findingId,
      target: error.target,
      type: error.type,
    })),
    stop_report: report.stopReport,
    stopped: report.stopped,
    dry_run: report.dryRun,
    judgment_candidates: report.judgmentCandidates,
    outcomes: report.outcomes.map((outcome) => ({
      finding_id: outcome.findingId,
      action: outcome.action,
      reason: outcome.reason,
    })),
  };
}

describe('triage dry-run planning: Python parity', () => {
  test('the fixture is present and non-trivial', () => {
    expect(fixture.cases.length).toBeGreaterThan(60);
  });

  for (const vector of fixture.cases) {
    if (vector.raises !== undefined) {
      test(`${vector.name}: Python raises ${vector.raises}, the port refuses`, () => {
        expect(() => replay(vector.input)).toThrow(TriagePlanRefusal);
      });
    } else if (vector.ts_refuses) {
      test(`${vector.name}: Python is lenient, the port is stricter`, () => {
        expect(() => replay(vector.input)).toThrow(TriagePlanRefusal);
      });
    } else {
      test(vector.name, () => {
        const outcome = replay(vector.input);
        expect(snake(outcome.result.report)).toEqual(vector.result);
        expect(outcome.repoCalls).toEqual(vector.repo_calls);
        expect(outcome.recoverCalls).toEqual(vector.recover_calls);
        expect(outcome.contextCalls).toEqual(vector.context_calls);
        expect(outcome.clockReads).toBe(vector.clock_reads);
      });
    }
  }
});

describe('triage dry-run planning: plan evidence', () => {
  // The dry-run report does not expose a plan's kwargs; these follow
  // `triage.py`'s `plans.append(...)` tuples and are asserted directly.
  const find = (name: string): TriagePlanResult => {
    const vector = fixture.cases.find((item) => item.name === name);
    if (vector === undefined) throw new Error(`no case ${name}`);
    return replay(vector.input).result;
  };

  test('a duplicate names the first canonical id', () => {
    const { plans } = find('exact-duplicates-point-at-first');
    expect(plans.map((plan) => [plan.findingId, plan.action, plan.evidence])).toEqual([
      ['d2', 'duplicate', { canonicalId: 'd1' }],
      ['d3', 'duplicate', { canonicalId: 'd1' }],
    ]);
  });

  test('a superseded plan carries the deleting commit only when Git named one', () => {
    const { plans } = find('deleted-path-is-superseded');
    expect(plans.map((plan) => [plan.findingId, plan.evidence])).toEqual([
      ['del1', { fixingCommit: 'f'.repeat(40) }],
      ['del2', {}],
    ]);
  });

  test('an unsettled earlier row seeds the canonical id, whatever happens to it', () => {
    // Each seed is skipped or planned itself; only its status keeps it canonical.
    for (const name of [
      'canonical-seed-needs-human-escalated',
      'canonical-seed-needs-human-skipped',
      'canonical-seed-unknown-status',
    ]) {
      const duplicate = find(name).plans.find((plan) => plan.action === 'duplicate');
      expect(duplicate?.findingId, name).toBe('n2');
      expect(duplicate?.evidence, name).toEqual({ canonicalId: 'n1' });
    }
  });

  test('pathless and investigation plans carry failureClass evidence', () => {
    const pathless = find('pathless-finding-needs-human').plans;
    expect(pathless.every((plan) => plan.evidence.failureClass === 'evidence')).toBe(true);
    const investigate = find('missing-evidence-regexes').plans;
    expect(investigate.length).toBeGreaterThan(0);
    expect(investigate.every((plan) => plan.evidence.failureClass === 'evidence')).toBe(true);
  });

  test('an escalated needs-human row is marked escalate on its plans', () => {
    const { plans } = find('pathless-finding-needs-human');
    expect(plans.map((plan) => [plan.findingId, plan.escalate])).toEqual([
      ['p-empty', false],
      ['p-null', false],
      ['p-null-needs-human', true],
    ]);
  });
});

describe('missingEvidence', () => {
  test('matches the Python predicate', () => {
    expect(missingEvidence('missing source evidence')).toBe(true);
    expect(missingEvidence('fixer investigation: missing source')).toBe(false);
    expect(missingEvidence('missing source: secret found')).toBe(false);
    expect(missingEvidence('owner decision required')).toBe(false);
    expect(missingEvidence(undefined)).toBe(false);
    expect(missingEvidence(7 as unknown as JsonValue)).toBe(false);
  });

  test('dotted and dotless I match ASCII i like Python re.I', () => {
    expect(missingEvidence('m\u0130ssing source')).toBe(true);
    expect(missingEvidence('m\u0131ssing source')).toBe(true);
    expect(missingEvidence('\u0131nvalid, missing context')).toBe(false);
    expect(missingEvidence('d\u0130spatch missing source')).toBe(false);
    expect(missingEvidence('missing source rate l\u0130m\u0130t')).toBe(false);
  });
});

describe('title casefold equality classes', () => {
  const titled = (titles: string[]): string[] => {
    const rows = titles.map((title, index) =>
      object({
        finding: {
          id: `t${String(index).padStart(2, '0')}`,
          severity: 'major',
          path: 'src/a.py',
          title,
          body: 'b',
          anchor_status: 'verified',
          blob: 'c'.repeat(40),
          intervals: [[1, 2]],
        },
        status: 'untriaged',
        review_id: 'r1',
        target: 'a'.repeat(40),
      }),
    );
    const out = planTriageDryRun({
      rows,
      reviews: [json({ id: 'r1', event_type: 'review', occurred_at: '2026-01-01T00:00:00Z' })],
      tip: 'b'.repeat(40),
      clock: () => 0,
      repo: {
        beginInvocation: () => undefined,
        commitDate: () => '',
        entryPaths: () => new Set(['src/a.py']),
        lineage: () => null,
        provenDeleted: () => false,
        deletingCommit: () => '',
      },
      prepareContext: () => ({ kind: 'ready' }),
    });
    return out.plans.map((plan) => plan.findingId);
  };

  test('folds like CPython for the cases that differ from upper-then-lower', () => {
    // t00 canonical; each later title that folds the same is a duplicate.
    expect(titled(['straße', 'STRASSE', 'STRAẞE'])).toEqual(['t01', 't02']);
    expect(titled(['ıi', 'Ii'])).toEqual([]);
    expect(titled(['Ꭰ', 'ꭰ'])).toEqual(['t01']);
    expect(titled(['ſtrasse', 'STRASSE'])).toEqual(['t01']);
  });
});
